// LC 560：统计连续子数组中和恰好等于 k 的个数
// 换题：改成是否存在时，getOrDefault 得到正数就返回 true；和可能超出 int 时保持 long
public static int subarraySum(int[] nums, int k) {
    Map<Long, Integer> cnt = new HashMap<>();
    cnt.put(0L, 1);
    // 空前缀，覆盖从下标 0 开始的子数组
    long pre = 0;
    int ans = 0;
    for (int x : nums) {
        pre += x;
        ans += cnt.getOrDefault(pre - k, 0);
        // 先查再写入，k 为 0 时不会把当前前缀算进自己
        cnt.merge(pre, 1, Integer::sum);
    }
    return ans;
}

// LC 862：数组可含负数，求和至少为 k 的最短连续子数组长度，不存在返回 -1
// 换题：元素都非负时改滑窗。若改成和小于 k 并输出那些数，下面两处 while 是按最短长度设计的，比较方向和答案都要重写
public static int shortestSubarray(int[] nums, int k) {
    int n = nums.length;
    long[] pre = new long[n + 1];
    for (int i = 0;
    i < n;
    i++) pre[i + 1] = pre[i] + nums[i];
    Deque<Integer> dq = new ArrayDeque<>();
    // 存前缀下标，对应的 pre 保持递增
    int ans = n + 1;
    for (int i = 0;
    i <= n;
    i++) {
        while (!dq.isEmpty() && pre[i] - pre[dq.peekFirst()] >= k) {
            ans = Math.min(ans, i - dq.pollFirst());
            // 这个左端点以后只会形成更长的区间
        }
        while (!dq.isEmpty() && pre[dq.peekLast()] >= pre[i]) dq.pollLast();
        dq.addLast(i);
    }
    return ans <= n ? ans : -1;
}

// LC 1109：bookings 每项为 [first, last, seats]，航班编号 1 到 n
// 在 first 加上座位数，在 last+1 减去，再前缀扫描得到每个航班的总座位
// 换题：0-based 闭区间 [l, r] 加 v 时，对长度 n 的 diff 执行 diff[l]+=v，且只在 r+1<n 时 diff[r+1]-=v；增量很大就把 diff 改成 long[]
public static int[] corpFlightBookings(int[][] bookings, int n) {
    int[] diff = new int[n + 2];
    for (int[] b : bookings) {
        diff[b[0]] += b[2];
        diff[b[1] + 1] -= b[2];
    }
    int[] ans = new int[n];
    for (int i = 1;
    i <= n;
    i++) {
        diff[i] += diff[i - 1];
        ans[i - 1] = diff[i];
    }
    return ans;
}

// LC 238：answer[i] 等于除 nums[i] 以外全部元素的乘积，不能用除法
// 先把左侧乘积写入 ans，再从右往左乘后缀积；数组里的 0 不需要单独分支
// 换题：改成除自身以外的和时，乘法换成加法，ans[0] 和 suf 的初值换成 0
public static int[] productExceptSelf(int[] nums) {
    int n = nums.length;
    int[] ans = new int[n];
    ans[0] = 1;
    for (int i = 1;
    i < n;
    i++) ans[i] = ans[i - 1] * nums[i - 1];
    int suf = 1;
    for (int i = n - 1;
    i >= 0;
    i--) {
        ans[i] *= suf;
        suf *= nums[i];
    }
    return ans;
}

