import java.util.*;
// 用哈希表按前缀和查历史次数
class Solution {
    public int subarraySum(int[] nums, int k) {
        // 只保存当前位置之前出现过的前缀和次数
        Map<Integer, Integer> frequency = new HashMap<>();
        frequency.put(0, 1);
        // 空前缀先记一次，从下标 0 开始的子数组才能被数到
        int prefix = 0;
        int answer = 0;
        for (int num : nums) {
            prefix += num;
            // 旧前缀等于 prefix-k 时，两段前缀之间的和正好是 k
            answer += frequency.getOrDefault(prefix - k, 0);
            // 查完再写入，当前前缀不能当作自己的历史端点
            frequency.put(prefix, frequency.getOrDefault(prefix, 0) + 1);
        }
        return answer;
    }
}

import java.util.*;
class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0;
        i < n;
        i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        Deque<Integer> deque = new ArrayDeque<>();
        int answer = n + 1;
        for (int right = 0;
        right <= n;
        right++) {
            // 队首已能与 right 组成和 ≥k 的区间，弹出它才能得到更短的合法区间。
            while (!deque.isEmpty()
            && prefix[right] - prefix[deque.peekFirst()] >= k) {
                answer = Math.min(answer, right - deque.pollFirst());
            }
            // 更晚且更小的 prefix[right] 作未来左端点更优，队尾更大的前缀可以丢掉。
            while (!deque.isEmpty()
            && prefix[deque.peekLast()] >= prefix[right]) {
                deque.pollLast();
            }
            deque.offerLast(right);
        }
        return answer == n + 1 ? -1 : answer;
    }
}

import java.util.Arrays;
public class SubarrayLessThanK {
    public int[] longestSubarrayLessThanKNonNegative(int[] nums, int k) {
        int left = 0;
        long sum = 0;
        // 还没找到合法窗口时用 -1 占位
        int bestLeft = -1, bestRight = -1;
        for (int right = 0;
        right < nums.length;
        right++) {
            sum += nums[right];
            // 非负数组里和只会随右扩变大，>= k 就必须从左边丢掉元素
            while (left <= right && sum >= k) {
                sum -= nums[left++];
            }
            if (left <= right && sum < k) {
                // 只保留目前最长的那一段
                if (bestLeft == -1 || right - left > bestRight - bestLeft) {
                    bestLeft = left;
                    bestRight = right;
                }
            }
        }
        if (bestLeft == -1) {
            return new int[0];
        }
        // copyOfRange 右端是开区间，所以要 bestRight + 1
        return Arrays.copyOfRange(nums, bestLeft, bestRight + 1);
    }
}

import java.util.*;
class Solution {
    public int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        // 写入后再乘 nums[i]，answer[i] 因此不含自身，只剩左侧积。
        int prefix = 1;
        for (int i = 0;
        i < n;
        i++) {
            answer[i] = prefix;
            prefix *= nums[i];
        }
        // 同样先乘入右侧积，再让 suffix 包含 nums[i]，避免乘到自己。
        int suffix = 1;
        for (int i = n - 1;
        i >= 0;
        i--) {
            answer[i] *= suffix;
            suffix *= nums[i];
        }
        return answer;
    }
}
